/* Approved home: v9 / 815e901. Detail routes only; no production API writes. */
(() => {
'use strict';
const L=(ko,en,zh,ja)=>({ko,en,zh,ja})[locale]||ko, esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cfg={contactEmail:'',youtube:'https://www.youtube.com/@KoreaSeriesOfPoker_official'}; // Verified recipient required before enabling email handoff.
const root=document.createElement('main');root.id='page-view';root.className='ksop-pages';root.hidden=true;$('#main').after(root);
const routes=['schedule','events','ranking','news','media','about','partners'], seriesIds=['next-series','season-program','partner-series'], playerIds=['example-a','example-b','example-c'];
const msg={pending:()=>L('공식 발표 예정','To be announced','待官方公布','正式発表をお待ちください'),home:()=>L('홈','Home','首页','ホーム'),all:()=>L('전체','All','全部','すべて'),details:()=>L('자세히 보기','View details','查看详情','詳細を見る'),back:()=>L('목록으로','Back to list','返回列表','一覧へ'),sample:()=>L('화면·계산 예시 · 공식 기록이 아닙니다.','Design and calculation examples · Not official results.','界面及计算示例，非官方成绩。','画面・計算例です。公式記録ではありません。'),soon:()=>L('준비중','Coming soon','即将上线','準備中')};
const label=id=>content[locale].nav[routes.indexOf(id)]||id;
const btn=(href,text)=>`<a class="pg-btn" href="#/${href}">${text}<span aria-hidden="true">↗</span></a>`;
const ext=(url,text,cls='pg-source')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${text} ↗</a>`;
const badge=(text=msg.pending())=>`<span class="pg-badge">${text}</span>`;
const note=text=>`<p class="pg-note">${text}</p>`;
const crumbs=items=>`<nav class="pg-breadcrumb" aria-label="${L('현재 위치','Breadcrumb','当前位置','現在地')}"><a href="#/">${msg.home()}</a>${items.map(([name,path])=>`<span aria-hidden="true">/</span>${path?`<a href="#/${path}">${name}</a>`:`<span aria-current="page">${name}</span>`}`).join('')}</nav>`;
const heading=(id,title,desc,extra='')=>`${crumbs([[label(id)]])}<div class="pg-heading"><h1 tabindex="-1">${title}</h1><p class="pg-lead">${desc}</p>${extra}</div>`;
const block=(title,html,extra='')=>`<section class="pg-block"><div class="pg-row"><h2>${title}</h2>${extra}</div>${html}</section>`;
const empty=text=>`<div class="pg-empty"><h3>${msg.pending()}</h3><p>${text}</p></div>`;
const img=(asset='arena.webp',alt='')=>`<img src="/motion/assets/${asset}" alt="${esc(alt)}" loading="lazy">`;
const filters=(name,items,current)=>`<div class="pg-filters" aria-label="${L('분류','Filters','筛选','絞り込み')}">${items.map(([v,t])=>`<button class="pg-filter" data-filter="${name}" data-value="${v}" aria-pressed="${current===v}">${t}</button>`).join('')}</div>`;
let scheduleFilter='upcoming',newsFilter='all',mediaFilterPage='all',query='';
function seriesName(i){return [L('다음 KSOP 시리즈','The next KSOP series','下一站 KSOP 系列赛','次のKSOPシリーズ'),L('KSOP 시즌 프로그램','KSOP season program','KSOP 赛季活动','KSOPシーズンプログラム'),L('파트너 연계 시리즈','Partner series','合作系列赛','パートナーシリーズ')][i]}
const seriesDesc=()=>L('선수의 집중과 전략이 만나는 다음 무대. 공식 일정과 장소가 확정되면 이곳에서 가장 먼저 안내합니다.','The next stage for focus and strategy. Confirmed dates and venues will be announced here.','专注与策略交汇的下一站。正式日程与场地确定后将在这里公布。','集中力と戦略が出会う次の舞台。日程と会場が確定次第、こちらでご案内します。');
const eventNames=()=>[L('메인 이벤트','Main event','主赛事','メインイベント'),L('사이드 이벤트','Side event','边赛','サイドイベント'),L('파이널 스테이지','Final stage','决赛阶段','ファイナルステージ')];
function seriesCard(i){return `<a class="pg-glass pg-lift" href="#/schedule/${seriesIds[i]}"><div class="pg-card-image">${img(i===1?'sculpture.webp':'arena.webp')}</div><div class="pg-card-copy">${badge()}<h3>${seriesName(i)}</h3><p>${L('일정·장소·프로그램 안내','Dates, venue and program','日程、场地及活动信息','日程・会場・プログラム')}</p><div class="pg-meta"><span>${msg.pending()}</span><span aria-hidden="true">↗</span></div></div></a>`}
function schedulePage(isEvents=false){return heading(isEvents?'events':'schedule',L('다음 무대를 만나세요.','Find your next stage.','寻找下一场精彩。','次の舞台へ。'),isEvents?L('먼저 시리즈를 선택하세요. 포함된 이벤트와 세부 안내를 한 화면에서 확인할 수 있습니다.','Choose a series first, then explore its events and details in one place.','请先选择系列赛，再查看其中的赛事与详细信息。','シリーズを選ぶと、各イベントと詳細をご覧いただけます。'):seriesDesc())+`<article class="pg-glass pg-banner"><div class="pg-banner-image">${img('arena.webp')}</div><div class="pg-banner-copy"><span class="pg-eyebrow">NEXT SERIES</span><h2>${seriesName(0)}</h2><p>${seriesDesc()}</p>${badge()}${btn('schedule/next-series',L('시리즈 살펴보기','Explore the series','浏览系列赛','シリーズを見る'))}</div></article>`+block(L('시리즈 일정','Series calendar','系列赛日程','シリーズ日程'),`<div class="pg-row">${filters('schedule',[['upcoming',L('예정','Upcoming','即将举行','開催予定')],['past',L('지난 시리즈','Past series','往届系列赛','過去のシリーズ')]],scheduleFilter)}</div><div class="pg-grid">${scheduleFilter==='past'?empty(L('확인된 지난 시리즈 기록이 등록되면 공개됩니다.','Verified past series will appear here.','经确认的往届系列赛记录将在此公布。','確認済みの過去のシリーズを掲載します。')):seriesIds.map((_,i)=>seriesCard(i)).join('')}</div>`)}
function seriesPage(id,eventId){const i=seriesIds.indexOf(id);if(i<0)return notFound();return crumbs([[label('schedule'),'schedule'],[seriesName(i)]])+`<div class="pg-heading"><span class="pg-eyebrow">KSOP SERIES</span><h1 tabindex="-1">${seriesName(i)}</h1><p class="pg-lead">${seriesDesc()}</p></div><div class="pg-glass pg-banner"><div class="pg-banner-image">${img('arena.webp')}</div><div class="pg-banner-copy">${badge()}<h2>${L('경기에 집중할 수 있는 무대.','A stage built for focus.','为专注而设的舞台。','競技に集中できる舞台。')}</h2><p>${L('일정, 장소, 경기 방식과 참가 안내를 간결하게 확인하세요.','Find dates, venue, format and participation information at a glance.','快速了解日程、场地、赛制与参与须知。','日程、会場、競技形式、参加案内をひと目で確認できます。')}</p></div></div><dl class="pg-facts">${[L('일정','Dates','日期','日程'),L('장소','Venue','场地','会場'),L('주최','Organizer','主办方','主催'),L('상태','Status','状态','状況')].map((s,j)=>`<div><dt>${s}</dt><dd>${j===2?'KSOP':msg.pending()}</dd></div>`).join('')}</dl>`+block(L('포함된 이벤트','Events in this series','系列赛事','シリーズ内イベント'),note(L('아래는 프로그램 구성 예시입니다. 공식 명칭과 시간·참가 조건은 발표 후 확정됩니다.','The program below is illustrative. Official names, times and eligibility will follow the announcement.','以下为活动结构示例。正式名称、时间及参与条件将在公布后确定。','以下はプログラムの構成例です。正式名称・時間・参加条件は発表後に確定します。'))+eventNames().map((name,j)=>`<details class="pg-glass pg-event" id="event-${j+1}" ${eventId===String(j+1)?'open':''}><summary><span class="pg-event-number">0${j+1}</span><span><strong>${name}</strong><small>${msg.pending()}</small></span>${badge()} </summary><div class="pg-event-body"><p>${L('공식 안내에 따라 경기 일정과 운영 규정을 확인할 수 있습니다.','Official event information will include the schedule and operating rules.','正式赛事说明将包含日程与竞赛规则。','公式案内で日程と運営ルールをご確認いただけます。')}</p><dl class="pg-facts">${[L('시작 시간','Start time','开始时间','開始時間'),L('접수 마감','Check-in deadline','签到截止','受付締切'),L('경기 방식','Format','赛制','形式'),L('참가 조건','Eligibility','参与条件','参加条件')].map(x=>`<div><dt>${x}</dt><dd>${msg.pending()}</dd></div>`).join('')}</dl><p>${L('변경 사항은 시리즈 공지에 반영합니다. 현재 참가 접수는 진행하지 않습니다.','Changes will appear in the series notices. Registration is not currently open.','变更将更新至系列赛公告。目前尚未开放报名。','変更事項はシリーズのお知らせに反映します。現在、参加受付は行っていません。')}</p><div class="pg-actions">${btn(`schedule/${id}/events/${j+1}`,L('이 이벤트 주소로 보기','Open event link','打开赛事链接','イベントのリンクを開く'))}${btn('news',L('관련 공지','Related news','相关公告','関連のお知らせ'))}</div></div></details>`).join(''))+`<div class="pg-actions">${btn('schedule',msg.back())}</div>`}
// Proposed non-monetary scoring. Preview only; does not replace the production ranking policy.
function score(n,r){if(!Number.isInteger(n)||!Number.isInteger(r)||n<2||r<1||r>n||r>Math.ceil(n*.15))return 0;return Math.round(1000*Math.sqrt(Math.min(n,1000)/100)*Math.pow((n-r)/(n-1),2))}
const results=[[[120,1],[180,8],[240,4]],[[120,3],[180,1],[240,16]],[[120,9],[180,12],[240,2]]];
const playerName=i=>L(`예시 선수 ${'ABC'[i]}`,`Example player ${'ABC'[i]}`,`示例选手 ${'ABC'[i]}`,`サンプル選手 ${'ABC'[i]}`);
const total=i=>results[i].map(([n,r])=>score(n,r)).sort((a,b)=>b-a).slice(0,10).reduce((a,b)=>a+b,0);
const tieBreak=i=>[total(i),Math.max(...results[i].map(([n,r])=>score(n,r))),results[i].filter(([,r])=>r===1).length,results[i].filter(([,r])=>r<=9).length];
const comparePlayers=(a,b)=>{const av=tieBreak(a),bv=tieBreak(b);for(let k=0;k<av.length;k++){if(av[k]!==bv[k])return bv[k]-av[k]}return 0};
const playerOrder=()=>[0,1,2].sort(comparePlayers);
const rankIndex=i=>playerOrder().findIndex(j=>comparePlayers(i,j)===0);
function playerCard(i,rank){return `<a class="pg-glass pg-lift pg-player" href="#/ranking/player/${playerIds[i]}"><div class="pg-avatar" aria-hidden="true">${'ABC'[i]}</div><div><span class="pg-eyebrow">0${rankIndex(i)+1} / SAMPLE</span><h3>${playerName(i)}</h3><div class="pg-score">${total(i).toLocaleString()}<small>PT</small></div></div></a>`}
function rankingPage(){const order=playerOrder();return heading('ranking',L('기록이 쌓여, 역사가 됩니다.','Every result tells a story.','让每一份成绩，成为历史。','記録が、歴史になる。'),L('시즌 순위와 선수별 입상 기록을 확인하세요. 각 점수의 산정 근거까지 투명하게 공개합니다.','Explore season standings and player results, with a clear explanation of every score.','查看赛季排名与选手成绩，了解每项积分的计算依据。','シーズン順位と選手の入賞記録を、ポイントの算出根拠とともにご覧ください。'),`<div class="pg-actions">${btn('ranking/method',L('점수 계산 방식','How points work','积分计算规则','ポイントの計算方法'))}</div>`)+note(msg.sample())+`<div class="pg-grid">${order.map((i,r)=>playerCard(i,r)).join('')}</div>`+block(L('시즌 랭킹','Season standings','赛季排名','シーズンランキング'),`<div class="pg-row"><span class="pg-badge">2026 · ${L('산정안 검토','Scoring proposal','计算方案待确认','算定案の確認中')}</span><label class="pg-search">${L('선수 검색','Find a player','搜索选手','選手を検索')}<input id="player-search" type="search" value="${esc(query)}" placeholder="${L('선수명','Player name','选手名称','選手名')}"></label></div><div class="pg-table-wrap"><table><thead><tr>${[L('순위','Rank','排名','順位'),L('선수','Player','选手','選手'),L('입상','Placements','入围','入賞'),L('우승','Wins','冠军','優勝'),L('파이널','Final tables','决赛桌','ファイナル'),L('포인트','Points','积分','ポイント')].map(t=>`<th scope="col">${t}</th>`).join('')}</tr></thead><tbody id="player-rows">${playerRows()}</tbody></table></div><p id="player-empty" class="pg-status" hidden>${L('검색 결과가 없습니다.','No matching players.','未找到匹配的选手。','該当する選手がいません。')}</p>`)}
function playerRows(){return playerOrder().map(i=>({i,r:rankIndex(i)})).filter(({i})=>playerName(i).toLowerCase().includes(query.toLowerCase())).map(({i,r})=>`<tr><td>${r+1}</td><td><a href="#/ranking/player/${playerIds[i]}">${playerName(i)} ↗</a></td><td>3</td><td>${results[i].filter(([,r])=>r===1).length}</td><td>${results[i].filter(([,r])=>r<=9).length}</td><td><strong>${total(i).toLocaleString()} PT</strong></td></tr>`).join('')}
function chart(values,caption){const max=Math.ceil(Math.max(...values,1)/500)*500,points=values.map((v,i)=>`${60+i*(460/Math.max(values.length-1,1))},${210-v/max*170}`);return `<svg class="pg-chart" viewBox="0 0 580 260" role="img" aria-label="${esc(caption)}"><title>${esc(caption)}</title>${[0,.5,1].map(r=>`<line class="pg-chart-grid" x1="50" x2="540" y1="${210-r*170}" y2="${210-r*170}"/><text x="4" y="${214-r*170}">${Math.round(max*r)}</text>`).join('')}<polyline class="pg-chart-line" points="${points.join(' ')}"/>${values.map((v,i)=>`<circle class="pg-chart-dot" cx="${60+i*(460/Math.max(values.length-1,1))}" cy="${210-v/max*170}" r="4"/><text text-anchor="middle" x="${60+i*(460/Math.max(values.length-1,1))}" y="242">${L('예시','Sample','示例','例')} ${i+1}</text><text text-anchor="middle" x="${60+i*(460/Math.max(values.length-1,1))}" y="${196-v/max*170}">${v}</text>`).join('')}</svg>`}
function playerPage(id){const i=playerIds.indexOf(id);if(i<0)return notFound();const scores=results[i].map(([n,r])=>score(n,r));let running=0;const cumulative=scores.map(v=>running+=v);return crumbs([[label('ranking'),'ranking'],[playerName(i)]])+note(msg.sample())+`<article class="pg-glass pg-pad pg-profile"><div class="pg-avatar" aria-label="${L('프로필 사진 자리','Profile photo placeholder','头像占位','プロフィール写真枠')}">${'ABC'[i]}</div><div><span class="pg-eyebrow">KSOP PLAYER / SAMPLE</span><h1 tabindex="-1">${playerName(i)}</h1><p>${L('공식 프로필과 결과가 등록되면 사진·소개·경기 기록이 연결됩니다.','A verified profile will connect the player photo, biography and results.','正式资料发布后，将展示选手照片、简介与比赛记录。','公式プロフィール公開後、写真・紹介・試合記録を掲載します。')}</p></div></article><dl class="pg-facts">${[[L('시즌 포인트','Season points','赛季积分','シーズンポイント'),`${total(i).toLocaleString()} PT`],[L('입상','Placements','入围','入賞'),'3'],[L('우승','Wins','冠军','優勝'),results[i].filter(([,r])=>r===1).length],[L('파이널 테이블','Final tables','决赛桌','ファイナルテーブル'),results[i].filter(([,r])=>r<=9).length]].map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl><div class="pg-two"><section class="pg-glass pg-pad"><h2>${L('누적 포인트','Cumulative points','累计积分','累積ポイント')}</h2>${chart(cumulative,L('예시 누적 포인트 변화. 아래 기록표에서 수치를 확인할 수 있습니다.','Example cumulative points. Values are available in the results table below.','示例累计积分，数值见下方成绩表。','累積ポイントの例。数値は下の記録表で確認できます。'))}</section><section class="pg-glass pg-pad"><h2>${L('대회별 획득 포인트','Points by event','各赛事积分','大会別ポイント')}</h2>${chart(scores,L('예시 대회별 포인트','Example points by event','示例赛事积分','大会別ポイントの例'))}</section></div>`+block(L('입상 전적과 산정 내역','Results and score breakdown','成绩及积分明细','入賞記録と算定内訳'),`<div class="pg-table-wrap"><table><thead><tr>${[L('기록','Record','记录','記録'),L('순위 / 참가자','Place / field','名次 / 人数','順位 / 人数'),L('규모 계수','Field factor','规模系数','規模係数'),L('순위 계수','Finish factor','名次系数','順位係数'),'PT',L('반영','Included','计入','反映')].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${results[i].map(([n,r],j)=>`<tr><td>${L('계산 예시','Calculation example','计算示例','計算例')} ${j+1}</td><td>${r} / ${n}</td><td>${Math.sqrt(n/100).toFixed(4)}</td><td>${Math.pow((n-r)/(n-1),2).toFixed(4)}</td><td>${scores[j]}</td><td>✓</td></tr>`).join('')}</tbody></table></div><div class="pg-actions">${btn('ranking/method',L('계산 근거 확인','See the calculation','查看计算依据','算出根拠を見る'))}${btn('ranking',msg.back())}</div>`)}
function methodPage(){return crumbs([[label('ranking'),'ranking'],[L('계산 방식','Scoring method','积分规则','算定方法')]])+`<div class="pg-heading"><span class="pg-eyebrow">KSOP RANKING / PROPOSAL</span><h1 tabindex="-1">${L('점수의 근거까지, 명확하게.','A clear basis for every point.','每一分，都有清晰依据。','ポイントの根拠まで、明確に。')}</h1><p class="pg-lead">${L('참가 규모와 최종 순위로 계산하는 KSOP 산정안입니다. 공식 규정 확정 전 검토용이며 기존 운영 랭킹을 변경하지 않습니다.','A proposed KSOP formula based on field size and finishing place. It is under review and does not change the current official ranking.','本方案根据参赛规模与最终名次计算。方案尚待确认，不改变现行官方排名。','参加規模と最終順位に基づくKSOP算定案です。確認用であり、現在の公式ランキングは変更しません。')}</p></div><div class="pg-glass pg-pad"><div class="pg-formula">P = round(1000 × √(min(N, 1000) / 100) × ((N − r) / (N − 1))²)</div><p class="pg-note">${L('N = 중복을 제외한 참가 선수 수 · r = 최종 순위 · P = 경기 포인트','N = unique players · r = final place · P = event points','N = 不重复参赛人数 · r = 最终名次 · P = 赛事积分','N = 重複を除く選手数 · r = 最終順位 · P = 大会ポイント')}</p><div class="pg-two"><div><h3>${L('시즌 합산 기준','Season aggregation','赛季汇总','シーズン集計')}</h3><p>${L('해당 연도 공식 승인 결과 중 상위 10개 점수만 합산합니다. 같은 이벤트는 선수별 최종 기록 1건만 반영하며 재참가 횟수는 참가 규모에 더하지 않습니다.','Sum the best 10 approved results in the calendar year. Count one final result per player per event; re-entries do not increase field size.','汇总当年已核准成绩中最高的10项积分。同一赛事每位选手仅计最终成绩一次，重入不增加参赛人数。','当年の承認済み結果から上位10件を合算。同じ大会では選手ごとに最終結果1件のみを計上し、リエントリーは人数に加算しません。')}</p></div><div><h3>${L('입상·동점 기준','Eligibility and ties','计分与并列规则','対象・同点ルール')}</h3><p>${L('2명 이상 참가한 경기에서 상위 15%(올림) 이내만 점수를 받습니다. 동점은 단일 최고점 → 우승 횟수 → 파이널 횟수 순으로 비교하고, 모두 같으면 공동 순위입니다. 파이널은 이 산정안에서 9위 이내로 정의합니다.','Points go to the top 15% (rounded up), with at least two unique players. Ties use best single score, wins, then final tables; remaining ties share rank. A final table means a top-nine finish in this proposal.','至少2人参赛，前15%（向上取整）获得积分。同分依次比较单项最高分、冠军次数、决赛桌次数；仍相同则并列。本方案将前9名定义为决赛桌。','2名以上の大会で上位15%（切り上げ）が対象。同点は最高単独ポイント、優勝数、ファイナル数の順で比較し、同じ場合は同順位。本案では9位以内をファイナルとします。')}</p></div></div></div>`+block(L('직접 계산해 보기','Try the calculation','试算积分','計算してみる'),`<form id="score-form" class="pg-glass pg-pad"><div class="pg-form-grid"><label class="pg-field">${L('참가 선수 수 N','Unique players N','参赛人数 N','参加選手数 N')}<input name="field" type="number" min="2" max="100000" step="1" value="100" required></label><label class="pg-field">${L('최종 순위 r','Final place r','最终名次 r','最終順位 r')}<input name="place" type="number" min="1" step="1" value="1" required></label></div><div class="pg-actions"><button type="submit" class="pg-btn">${L('계산하기','Calculate','计算','計算する')}</button><output id="score-output" class="pg-score" aria-live="polite">1,000 <small>PT</small></output></div><p id="score-note" class="pg-status">${L('100명 중 1위 = 1,000 PT','1st of 100 = 1,000 PT','100人中第1名 = 1,000 PT','100名中1位 = 1,000 PT')}</p></form>`)+block(L('참고 기준과 KSOP의 방향','References and KSOP direction','参考依据与 KSOP 方向','参考基準とKSOPの方針'),`<p>${L('GPI는 순위·참가 규모와 함께 참가 금액 및 기록의 경과 기간을 반영합니다. KSOP 검토안은 금액 요소를 제외하고 경기 성적을 중심으로 단순화했습니다. GPI·JOPT 공식 점수와는 직접 비교할 수 없습니다.','GPI incorporates finishing place, field size, buy-in and recency. This KSOP proposal removes monetary factors and focuses on sporting results. Its points are not directly comparable to GPI or JOPT.','GPI考虑名次、人数、参赛金额及成绩时间。本KSOP方案去除金额因素，简化为竞技成绩指标，不能与GPI或JOPT积分直接比较。','GPIは順位、人数、参加金額、経過期間を反映します。KSOP案は金額要素を除き競技成績を中心に簡素化しました。GPI・JOPTの点数との直接比較はできません。')}</p><div class="pg-actions">${ext('https://www.globalpokerindex.com/about/','GPI · '+L('계산 기준','Methodology','计算规则','算定基準'))}${ext('https://ranking.japanopenpoker.com/','JOPT · Grand Poker Ranking')}</div>`)}
const newsIds=['ksop-jopt','series-guide','champion-interview'];
function newsData(){return [
{id:newsIds[0],category:'series',title:L('KSOP × JOPT, 한·일 교류의 무대를 넓히다','KSOP × JOPT: connecting players across borders','KSOP × JOPT：拓展韩日交流舞台','KSOP × JOPT、日韓交流の舞台を広げる'),intro:L('선수 교류와 대회 운영 인력의 협력을 위한 파트너십.','A partnership for player exchange and cooperation between event teams.','促进选手交流与赛事运营人员合作。','選手交流と大会運営スタッフの連携に向けた提携。'),date:'2024.04.30',asset:'arena.webp',body:L('JOPT는 KSOP 및 한국홀덤협회와의 업무 제휴를 발표했습니다. 양측은 선수 교류와 운영 인력 양성을 협력 방향으로 제시했습니다. 이번 소식은 JOPT의 공식 발표를 바탕으로 요약한 아카이브입니다.','JOPT announced a partnership with KSOP and the Korea Holdem Association, with player exchanges and event-staff development among its goals. This archive summarizes JOPT’s official announcement.','JOPT宣布与KSOP及韩国德州扑克协会合作，旨在促进选手交流与赛事工作人员培养。本文根据JOPT正式公告整理。','JOPTはKSOPおよび韓国ホールデム協会との提携を発表。選手交流と運営スタッフ育成を目標としています。JOPTの公式発表に基づくアーカイブです。'),source:'https://japanopenpoker.com/ksop_jopt/'},
{id:newsIds[1],category:'notice',title:L('시리즈부터 이벤트까지, 한눈에 확인하세요','Your guide from series to event','从系列赛到具体赛事，一目了然','シリーズからイベントまで、ひと目で'),intro:L('일정 확인과 이벤트 상세 안내를 찾는 방법.','How to find series schedules and event information.','如何查看系列赛日程与赛事详情。','日程とイベントの詳細を探す方法。'),date:L('이용 안내','Site guide','使用指南','ご利用ガイド'),asset:'arena.webp',body:L('일정에서 관심 있는 시리즈를 선택하면 개최 정보와 포함된 이벤트를 확인할 수 있습니다. 이벤트 제목을 누르면 시작 시간, 접수 마감, 경기 방식과 참가 조건이 아래로 펼쳐집니다. 확정 전 정보는 발표 예정으로 표시하며, 변경 사항은 관련 공지를 통해 안내합니다.','Choose a series in Schedule to see its venue information and event list. Select an event title to expand its start time, check-in deadline, format and eligibility. Unconfirmed information is marked as pending, and changes will appear in related notices.','在日程页选择感兴趣的系列赛，即可查看举办信息与赛事列表。点击赛事标题，可展开时间、签到截止、赛制及参与条件。未确定的信息会标注为待公布，变更将通过相关公告说明。','日程ページでシリーズを選ぶと、開催情報とイベント一覧を確認できます。タイトルを押すと開始時間、受付締切、形式、参加条件が開きます。未確定の情報は発表予定とし、変更は関連のお知らせでご案内します。')},
{id:newsIds[2],category:'interview',title:L('우승의 순간, 그 이후의 이야기','The story beyond the victory','胜利之后的故事','優勝の瞬間、その先の物語'),intro:L('우승자 사진과 인터뷰 기사를 이곳에서 만나보세요.','Champion portraits and editorial interviews will appear here.','在这里阅读冠军照片与专访。','優勝者の写真とインタビュー記事をお届けします。'),date:msg.soon(),asset:'sculpture.webp',body:L('우승자 인터뷰는 사진과 글 중심의 뉴스 콘텐츠로 소개합니다. 선수 소개, 결정적인 순간, 대회를 준비한 과정과 다음 목표를 담을 예정입니다. 실제 인터뷰 원문과 사진이 확인되면 공개하며, 현재 선수의 발언이나 전적을 임의로 작성하지 않았습니다.','Champion interviews belong to our photo and editorial news collection. They will explore the player, decisive moments, preparation and future goals. The article will be published once the interview and photos are verified; no player quotes or results have been invented.','冠军专访以照片与文章形式归入新闻，讲述选手、关键时刻、备赛过程与未来目标。采访原文和照片确认后再发布，目前未编造选手发言或成绩。','優勝者インタビューは写真と記事を中心とするニュースで紹介します。選手、決定的な場面、準備、次の目標を掲載予定です。原稿と写真の確認後に公開し、発言や成績は創作していません。')}
]}
const newsCategory=id=>({notice:L('공지·안내','Notices','公告','お知らせ'),series:L('시리즈 소식','Series news','系列赛新闻','シリーズニュース'),interview:L('우승자 인터뷰','Champion interviews','冠军专访','優勝者インタビュー')})[id];
function newsCard(n){return `<a class="pg-glass pg-lift" href="#/news/${n.id}"><div class="pg-card-image">${img(n.asset)}</div><div class="pg-card-copy"><span class="pg-eyebrow">${newsCategory(n.category)}</span><h3>${n.title}</h3><p>${n.intro}</p><div class="pg-meta"><span>${n.date}</span><span aria-hidden="true">↗</span></div></div></a>`}
function newsPage(){return heading('news',L('무대 안팎의 이야기.','Stories on and off the stage.','舞台内外的故事。','舞台の内側も、その外側も。'),L('공식 공지, 시리즈 소식, 그리고 우승자의 이야기. KSOP의 새로운 순간을 기록합니다.','Official notices, series updates and champion stories. A record of KSOP’s moments.','官方公告、系列赛动态与冠军故事，记录KSOP的精彩时刻。','公式のお知らせ、シリーズの話題、優勝者の物語。KSOPの瞬間を記録します。'))+`<div class="pg-row">${filters('news',[['all',msg.all()],...['notice','series','interview'].map(v=>[v,newsCategory(v)])],newsFilter)}</div><div class="pg-grid">${newsData().filter(n=>newsFilter==='all'||n.category===newsFilter).map(newsCard).join('')}</div>`}
function articlePage(id){const n=newsData().find(n=>n.id===id);if(!n)return notFound();return `<article class="pg-article">${crumbs([[label('news'),'news'],[newsCategory(n.category)]])}<span class="pg-eyebrow">${newsCategory(n.category)}</span><h1 tabindex="-1">${n.title}</h1><p class="pg-lead">${n.intro}</p><div class="pg-meta"><span>${n.date}</span><span>KSOP STUDIO</span></div><figure class="pg-article-cover">${img(n.asset)}</figure><p class="pg-caption">${L('KSOP 브랜드 콘셉트 이미지','KSOP brand concept image','KSOP 品牌概念图','KSOPブランドコンセプト画像')}</p><div class="pg-prose"><p>${n.body}</p>${n.category==='interview'?`<h2>${L('기록할 질문들','Questions to explore','即将记录的问题','記録したい問い')}</h2>${[L('가장 오래 기억에 남을 순간은 무엇인가요?','Which moment will stay with you?','哪一刻最令您难忘？','最も記憶に残る瞬間は？'),L('무대를 준비하며 가장 집중했던 것은 무엇인가요?','What did you focus on while preparing?','备赛时最关注什么？','準備で最も力を入れたことは？'),L('다음 무대에서 이루고 싶은 목표는 무엇인가요?','What is your goal for the next stage?','下一场比赛的目标是什么？','次の舞台での目標は？')].map(q=>`<details class="pg-event pg-glass"><summary><span>Q</span><strong>${q}</strong></summary><div class="pg-event-body">${L('실제 인터뷰 공개 후 답변이 등록됩니다.','The answer will be added when the interview is published.','正式专访发布后将添加回答。','正式なインタビュー公開後に回答を掲載します。')}</div></details>`).join('')}`:''}</div>${n.source?ext(n.source,L('JOPT 공식 발표 원문','Official JOPT announcement','JOPT 官方公告原文','JOPT公式発表')):''}<div class="pg-actions">${btn('news',msg.back())}${btn(n.category==='interview'?'media':'schedule',n.category==='interview'?label('media'):label('schedule'))}</div></article>`+block(L('다른 소식','More stories','更多新闻','ほかのニュース'),`<div class="pg-grid">${newsData().filter(v=>v.id!==id).map(newsCard).join('')}</div>`)}
const verifiedVideos=[{id:'0nJaWopMjwo',type:'highlights',title:'WPL X KSOP LIVESERIES SEASON3'},{id:'YSPq5RWK3dU',type:'behind',title:'WPL Live Seires By KSOP 현장스케치!'},{id:'F-Kb9Iz0Z2g',type:'full',title:'2022 WPL X KSOP LIVE SERIES MAIN EVENT DAY-1A 대구'}];
function mediaPage(){const names={all:msg.all(),highlights:L('하이라이트','Highlights','精彩集锦','ハイライト'),behind:L('현장 스케치','Behind the scenes','现场花絮','舞台裏'),full:L('경기 영상','Event videos','赛事视频','競技映像'),shorts:L('숏츠','Shorts','短视频','ショート')};const videos=verifiedVideos.filter(v=>mediaFilterPage==='all'||mediaFilterPage===v.type);const pendingCount=mediaFilterPage==='all'?9:mediaFilterPage==='shorts'?6:3;return heading('media',L('경기의 순간을, 오래도록.','Keep the moments alive.','让精彩瞬间长久留存。','競技の瞬間を、いつまでも。'),L('KSOP STUDIO는 경기 영상, 하이라이트, 숏츠와 현장 이야기를 기록합니다. 썸네일을 선택하면 공식 유튜브 영상으로 이동합니다.','KSOP STUDIO captures events, highlights, shorts and behind-the-scenes stories. Choose a thumbnail to watch on the official YouTube channel.','KSOP STUDIO记录赛事、集锦、短视频与幕后故事。点击缩略图即可前往官方YouTube观看。','KSOP STUDIOは試合、ハイライト、ショート、舞台裏を記録します。サムネイルから公式YouTubeの動画へ移動します。'),`<div class="pg-actions">${ext(cfg.youtube,L('공식 유튜브 전체보기','Official YouTube channel','官方YouTube频道','公式YouTubeを見る'),'pg-btn')}${btn('news?category=interview',L('사진·기사로 읽는 우승자 인터뷰','Champion interviews in photos and words','照片与文字冠军专访','写真と記事で読む優勝者インタビュー'))}</div>`)+`<div class="pg-row">${filters('media',Object.entries(names),mediaFilterPage)}<span class="pg-eyebrow">KSOP STUDIO / ARCHIVE</span></div><div class="pg-grid pg-video-grid">${videos.map(v=>`<a class="pg-glass pg-lift pg-video" href="https://www.youtube.com/watch?v=${v.id}" target="_blank" rel="noopener noreferrer" aria-label="${esc(v.title)} · YouTube"><img src="/motion/assets/media/${v.id}.jpg" alt="${esc(v.title)}" loading="lazy"><span class="pg-video-caption">${esc(v.title)}</span></a>`).join('')}${Array.from({length:pendingCount},(_,i)=>`<div class="pg-glass pg-lift pg-video-pending" tabindex="0" aria-label="KSOP STUDIO · ${msg.soon()}"><span>KSOP ${i%3===0?'SHORTS':i%3===1?'HIGHLIGHTS':'STORIES'}</span><span class="soon-badge">${msg.soon()}</span></div>`).join('')}</div><p class="pg-status">${L('공개 주소가 확인된 영상부터 연결했습니다. 새로운 영상은 공식 공개 후 추가됩니다.','Verified public videos are linked first. New releases will be added after publication.','已连接经确认的公开视频，新视频将在正式发布后加入。','公開URLを確認できた動画から掲載しています。新しい映像は正式公開後に追加します。')}</p>`}
const partnerDescriptions=()=>[
L('일본의 포커 토너먼트 브랜드. KSOP와 선수 교류 및 대회 운영 협력을 이어갑니다.','A Japanese tournament brand collaborating with KSOP on player exchange and event operations.','日本扑克赛事品牌，与KSOP推进选手交流及赛事运营合作。','日本のトーナメントブランド。KSOPと選手交流・大会運営で連携します。'),
L('중국의 포커 토너먼트 브랜드. 공식 홈페이지에서 시리즈와 대회 소식을 확인할 수 있습니다.','A Chinese tournament brand. Visit its official website for series and event news.','中国扑克赛事品牌，可在官网查看系列赛与赛事新闻。','中国のトーナメントブランド。シリーズや大会の情報は公式サイトへ。'),
L('국제 토너먼트 선수 기록과 순위 정보를 제공하는 글로벌 랭킹 서비스.','A global ranking service for international tournament players and results.','提供国际赛事选手记录与排名信息的全球服务。','国際トーナメントの選手記録と順位を提供するランキングサービス。'),
L('앱과 게임을 비롯한 디지털 제품의 기획·개발을 담당하는 기술 브랜드.','A technology brand for planning and developing apps, games and digital products.','专注应用、游戏及数字产品策划与开发的技术品牌。','アプリ、ゲーム、デジタル製品の企画・開発を担う技術ブランド。'),
L('매장과 현장 운영 경험을 연결하는 공간·운영 브랜드.','A venue and operations brand connecting spaces with on-site experiences.','连接场馆与现场运营体验的空间运营品牌。','店舗と現場体験をつなぐ空間・運営ブランド。'),
L('이벤트, 기록, 커뮤니티와 회원 경험을 연결하는 서비스 브랜드.','A service brand connecting events, records, community and member experiences.','连接赛事、记录、社区与会员体验的服务品牌。','イベント、記録、コミュニティ、会員体験をつなぐサービスブランド。')];
function partnersPage(){return heading('partners',L('함께 만드는 다음 무대.','The next stage, together.','共同打造下一站。','次の舞台を、ともに。'),L('대회, 기술, 공간과 콘텐츠. 서로의 전문성을 연결해 더 나은 경험을 만듭니다.','Tournaments, technology, spaces and content. Connecting expertise to create better experiences.','赛事、技术、空间与内容，连接专业力量，创造更好的体验。','大会、技術、空間、コンテンツ。それぞれの専門性で、よりよい体験をつくります。'))+`<div class="pg-grid">${partners.map((p,i)=>`<article class="pg-glass pg-pad pg-partner pg-lift">${p.url?`<a class="pg-partner-mark" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(p.name)} · ${L('공식 홈페이지','Official website','官方网站','公式サイト')}">${partnerLogo(p)}</a>`:`<span class="pg-partner-mark" tabindex="0" role="link" aria-disabled="true" aria-label="${esc(p.name)} · ${msg.soon()}">${partnerLogo(p)}<span class="soon-badge">${msg.soon()}</span></span>`}<h3>${esc(p.name)}</h3><p>${partnerDescriptions()[i]}</p>${p.url?ext(p.url,L('공식 홈페이지','Official website','官方网站','公式サイト')):''}</article>`).join('')}</div>`+block(L('새로운 협력을 제안하세요.','Propose a new collaboration.','开启新的合作。','新しい協力をご提案ください。'),`<p>${L('브랜드와 무대가 만나는 가장 좋은 방법을 함께 찾겠습니다.','Let’s find the right way to connect your brand with the stage.','共同寻找品牌与舞台相遇的最佳方式。','ブランドと舞台をつなぐ最適な方法を一緒に考えます。')}</p><div class="pg-actions">${btn('about/apply/partner',L('파트너 신청','Become a partner','申请合作','パートナーの申し込み'))}</div>`)}
function aboutSection(type){if(type==='company')return `<section class="pg-about"><div>${img('sculpture.webp')}</div><div><span class="pg-eyebrow">KOREA SERIES OF POKER</span><h2>${L('정교한 운영.<br>오래 남는 경험.','Precise operations.<br>Lasting experiences.','精细运营。<br>长久体验。','精緻な運営。<br>心に残る体験。')}</h2><p>${L('KSOP는 선수와 경기 경험을 중심에 두는 토너먼트 대회사입니다. 대회 운영, 선수 기록, 미디어와 브랜드 협업을 통해 마인드스포츠의 무대를 만들어갑니다.','KSOP is a tournament organizer centered on players and their experience. We build mind-sports stages through event operations, player records, media and brand collaboration.','KSOP以选手与比赛体验为核心，通过赛事运营、选手记录、媒体与品牌合作打造智力运动舞台。','KSOPは選手と競技体験を中心に考える大会運営会社です。大会運営、選手記録、メディア、ブランド協業を通じてマインドスポーツの舞台をつくります。')}</p><div class="pg-meta"><span>${L('정교함','Precision','精确','精緻さ')}</span><span>${L('존중','Respect','尊重','尊重')}</span><span>${L('경험','Experience','体验','体験')}</span></div></div></section>`;
if(type==='greeting')return `<article class="pg-glass pg-pad"><span class="pg-eyebrow">MESSAGE</span><h2>${L('사람과 경기가 오래 기억되는 무대를.','A stage where people and competition endure.','让人与比赛的记忆长久留存。','人と競技が、長く記憶に残る舞台を。')}</h2><div class="pg-prose"><p>${L('KSOP가 지향하는 것은 한 번의 대회로 끝나지 않는 경험입니다. 선수에게는 집중할 수 있는 환경을, 팬에게는 함께 즐길 이야기를, 파트너에게는 함께 성장할 기회를 만들고자 합니다.','Our aim is an experience that lasts beyond a single event: a focused environment for players, stories for fans to share, and opportunities for partners to grow together.','我们希望体验不止于一场比赛：为选手提供专注的环境，为观众创造共同分享的故事，为合作伙伴创造共同成长的机会。','一度の大会で終わらない体験を目指します。選手には集中できる環境、ファンには共有できる物語、パートナーには共に成長できる機会をつくります。')}</p><p>${L('정교한 운영과 서로에 대한 존중을 바탕으로, 다음 무대를 한 걸음씩 준비하겠습니다.','With precise operations and mutual respect, we will build the next stage one step at a time.','以精细运营和相互尊重为基础，一步步准备下一站。','精緻な運営と互いへの敬意を土台に、次の舞台を一歩ずつ準備します。')}</p></div><span class="pg-eyebrow">KSOP · ${L('대표 인사말 검토 원고','Draft greeting for review','代表致辞待审稿','代表挨拶・確認用原稿')}</span></article>`;
return `<div class="pg-timeline">${[[L('시작','Beginning','起点','始まり'),L('체계적인 대회 운영을 향해','Toward structured tournament operations','迈向系统化赛事运营','体系的な大会運営へ'),L('선수와 경기 경험을 중심으로 대회의 기초를 다집니다.','Building tournament foundations around players and their experience.','围绕选手与比赛体验奠定赛事基础。','選手と競技体験を軸に大会の基礎を築きます。')],[L('구축','Development','构建','構築'),L('기록과 운영을 연결하다','Connecting records and operations','连接记录与运营','記録と運営をつなぐ'),L('대회 운영, 선수 기록, 콘텐츠와 파트너 협업 구조를 발전시킵니다.','Developing operations, player records, content and partner collaboration.','完善赛事运营、选手记录、内容与合作机制。','大会運営、選手記録、コンテンツ、協業の仕組みを整えます。')],['2024',L('JOPT와 한·일 협력','Japan–Korea cooperation with JOPT','与JOPT推进韩日合作','JOPTとの日韓連携'),L('선수 교류와 운영 인력 양성을 위한 업무 제휴를 발표했습니다.','A partnership announced for player exchange and event-staff development.','宣布促进选手交流与赛事工作人员培养的合作。','選手交流と運営スタッフ育成に向けた提携を発表。')],[L('다음','Next','下一步','これから'),L('더 넓은 무대로','Toward a broader stage','迈向更广阔的舞台','より広い舞台へ'),L('국내와 아시아의 대회·미디어·파트너 경험을 연결하는 방향을 지향합니다.','Aiming to connect tournament, media and partner experiences across Korea and Asia.','致力于连接韩国与亚洲的赛事、媒体及合作体验。','韓国とアジアの大会・メディア・パートナー体験をつなぐことを目指します。')]].map(([date,title,text])=>`<article><span class="pg-eyebrow">${date}</span><h3>${title}</h3><p>${text}</p></article>`).join('')}</div>${ext('https://japanopenpoker.com/ksop_jopt/',L('2024 협력 발표 확인','2024 partnership announcement','2024年合作公告','2024年の提携発表'))}`}
const applyNames=()=>({sponsor:L('협찬기업 신청','Sponsorship','赞助申请','協賛の申し込み'),mice:L('MICE 기업 신청','MICE collaboration','MICE企业申请','MICE企業の申し込み'),partner:L('파트너 신청','Partnership','合作申请','パートナーの申し込み')});
function applyCards(){return `<div class="pg-grid">${Object.entries(applyNames()).map(([id,title],i)=>`<a class="pg-glass pg-pad pg-lift" href="#/about/apply/${id}"><span class="pg-eyebrow">WORK WITH KSOP</span><h3>${title}</h3><p>${[L('브랜드 협찬과 현장 경험을 제안하세요.','Propose brand sponsorship and on-site experiences.','提议品牌赞助与现场体验合作。','ブランド協賛と現場体験をご提案ください。'),L('지역 행사·컨벤션·관광·복합 이벤트를 함께 기획합니다.','Collaborate on regional events, conventions, tourism and combined programs.','共同策划地区活动、会展、旅游及综合项目。','地域イベント、コンベンション、観光、複合企画で協力します。'),L('대회·기술·공간·콘텐츠의 협력 가능성을 나눕니다.','Explore partnerships in events, technology, venues and content.','探索赛事、技术、场地及内容合作。','大会・技術・空間・コンテンツの連携を相談します。')][i]}</p><span aria-hidden="true">↗</span></a>`).join('')}</div>`}
function aboutPage(focus){const sections={company:L('회사 소개','Company','公司介绍','会社紹介'),greeting:L('대표 인사','Greeting','代表致辞','代表挨拶'),history:L('연혁','Our journey','发展历程','歩み')};if(focus&&!sections[focus])return notFound();return heading('about',L('경험을 만드는 사람들.','The people behind the experience.','创造体验的人们。','体験をつくる人たち。'),L('대회 운영부터 기록, 콘텐츠와 파트너십까지. KSOP가 준비하는 다음 무대를 소개합니다.','From tournament operations to records, content and partnerships. Discover what KSOP is building next.','从赛事运营到记录、内容与合作，了解KSOP正在准备的下一站。','大会運営から記録、コンテンツ、パートナーシップまで。KSOPが準備する次の舞台をご紹介します。'))+`<nav class="pg-subnav" aria-label="${label('about')}">${Object.entries(sections).map(([id,title])=>`<a href="#/about/${id}" ${focus===id?'aria-current="page"':''}>${title}</a>`).join('')}</nav>`+(focus?block(sections[focus],aboutSection(focus)):Object.entries(sections).map(([id,title])=>block(title,aboutSection(id))).join(''))+block(L('KSOP와 함께 만들기','Build with KSOP','与KSOP共创','KSOPとともにつくる'),applyCards())}
function applyPage(type){if(!applyNames()[type])return notFound();return crumbs([[label('about'),'about'],[applyNames()[type]]])+`<div class="pg-heading"><span class="pg-eyebrow">WORK WITH KSOP</span><h1 tabindex="-1">${applyNames()[type]}</h1><p class="pg-lead">${L('제안 내용을 작성하고 확인한 뒤 회사 메일로 전달하는 문의 창구입니다.','Prepare and review your proposal, then send it to the company by email.','填写并核对合作提议，再通过邮件发送给公司。','ご提案を記入・確認し、会社のメール窓口へ送るお問い合わせです。')}</p></div>${!cfg.contactEmail?note(L('회사 수신 메일 확인 전입니다. 문의 초안은 작성·복사할 수 있으며, 메일 발송은 아직 연결되지 않았습니다.','The company recipient is awaiting confirmation. You can prepare and copy a draft; email sending is not connected yet.','公司收件地址待确认。可编写并复制草稿，邮件发送暂未连接。','会社の受信アドレスを確認中です。下書きの作成・コピーはできますが、メール送信は未接続です。')):''}<form id="inquiry-form" class="pg-glass pg-pad" data-type="${type}"><div class="pg-form-grid">${[['company',L('회사·기관명','Company / organization','公司 / 机构','会社・団体名'),'text'],['name',L('담당자명','Contact name','联系人','担当者名'),'text'],['email',L('회신 이메일','Reply email','回复邮箱','返信先メール'),'email'],['phone',L('연락처 (선택)','Phone (optional)','电话（选填）','電話番号（任意）'),'tel']].map(([name,title,t])=>`<label class="pg-field">${title}<input name="${name}" type="${t}" maxlength="${name==='email'?254:100}" ${name==='phone'?'':'required'} autocomplete="${({company:'organization',name:'name',email:'email',phone:'tel'})[name]}"></label>`).join('')}<label class="pg-field pg-wide">${L('제안 내용','Proposal','提议内容','ご提案内容')}<textarea name="message" maxlength="1400" required></textarea></label><label class="pg-check pg-wide"><input type="checkbox" name="consent" required><span>${L('입력한 연락처와 제안 내용을 KSOP 문의 메일에 포함하는 데 동의합니다. 이 화면에서는 입력 내용을 서버에 저장하지 않습니다.','I agree to include my contact details and proposal in the email to KSOP. This page does not save the information on a server.','同意将联系方式与提议内容包含在发给KSOP的邮件中。本页面不会将输入内容保存至服务器。','連絡先と提案内容をKSOPへのメールに含めることに同意します。この画面では入力内容をサーバーに保存しません。')}</span></label></div><div class="pg-actions"><button class="pg-btn" type="submit">${L('문의 내용 확인','Review proposal','核对内容','内容を確認')}</button></div><div id="inquiry-review" class="pg-block" hidden><h2>${L('문의 내용 미리보기','Proposal preview','提议预览','お問い合わせの確認')}</h2><pre id="inquiry-text" style="white-space:pre-wrap;font:inherit;overflow-wrap:anywhere"></pre><div class="pg-actions"><button id="copy-inquiry" class="pg-btn" type="button">${L('초안 복사','Copy draft','复制草稿','下書きをコピー')}</button><a id="mail-inquiry" class="pg-btn" ${cfg.contactEmail?'':'aria-disabled="true" tabindex="-1"'}>${L('메일 앱에서 발송','Send with email app','在邮件应用中发送','メールアプリで送信')}</a></div></div><p id="inquiry-status" class="pg-status" role="status" aria-live="polite"></p></form>`}
function notFound(){return crumbs([[L('페이지를 찾을 수 없습니다','Page not found','未找到页面','ページが見つかりません')]])+`<div class="pg-heading"><span class="pg-eyebrow">404</span><h1 tabindex="-1">${L('다시 무대로 돌아가세요.','Return to the stage.','回到精彩舞台。','舞台へ戻りましょう。')}</h1><p>${L('주소가 변경되었거나 공개되지 않은 페이지입니다.','This page has moved or is not published.','此页面已更改或尚未公开。','URLが変更されたか、未公開のページです。')}</p><div class="pg-actions">${btn('',msg.home())}${btn('schedule',label('schedule'))}</div></div>`}
function contactPage(){return heading('about',L('이야기를 시작하세요.','Start a conversation.','开始对话。','お話を始めましょう。'),L('문의 유형을 선택해 제안 내용을 남겨주세요.','Choose the type of collaboration and prepare your proposal.','选择合作类型并填写提议。','お問い合わせの種類を選び、ご提案をご記入ください。'))+applyCards()}
function footer(){return `<footer class="pg-footer"><span>© 2026 KSOP. ${L('모든 권리 보유.','ALL RIGHTS RESERVED.','保留所有权利。','ALL RIGHTS RESERVED.')}</span><div><a href="/privacy">${t('privacy')}</a><a href="/terms">${t('terms')}</a><a href="#/contact">${t('contact')}</a></div></footer>`}
function wireHome(){
 document.querySelectorAll('.brand').forEach(a=>a.href='#/');
 document.querySelectorAll('#main [data-detail],#main [data-collection]').forEach(a=>{const section=a.closest('section')?.id;let path=({rankings:'ranking'})[section]||section||'contact';if(a.dataset.detail==='privacy'||a.dataset.detail==='terms')return;if(section==='news'&&a.closest('#news-highlights'))path='news/'+newsIds[[...a.parentElement.children].indexOf(a)];else if(section==='rankings'&&a.closest('#rank-highlights'))path='ranking/player/'+playerIds[[...a.parentElement.children].indexOf(a)];else if(section==='schedule'&&a.classList.contains('series-card'))path='schedule/'+seriesIds[[...a.parentElement.children].indexOf(a)];else if(section==='top')path=a.dataset.detail==='events'?'events':'schedule';if(!routes.includes(path.split('/')[0])&&path!=='contact')path='contact';a.href='#/'+path;a.removeAttribute('data-detail');a.removeAttribute('data-collection')});
 document.querySelectorAll('.hero-action-links a,.next-series-card,.hero-info-rail a').forEach(a=>{a.href=a.textContent.includes(content[locale].actionEvents)?'#/events':'#/schedule'});
}
let routeSerial=0;
const livePic=s=>`<img src="${esc(window.KSOPCMS.url(s)||'/motion/assets/arena.webp')}" alt="" loading="lazy">`;
const liveText=s=>String(s||'').split(/\n\s*\n/).map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('');
const liveDate=s=>s?new Date(s).toLocaleString(locale==='ko'?'ko-KR':locale==='zh'?'zh-CN':locale==='ja'?'ja-JP':'en-US',{timeZone:'Asia/Seoul',dateStyle:'medium',timeStyle:'short'}):msg.pending();
const liveEmpty=()=>empty(L('공식 콘텐츠가 등록되면 표시됩니다.','Confirmed content will appear here.','正式内容发布后将在此显示。','公式情報の公開をお待ちください。'));
const pager=d=>d.total>d.pageSize?`<nav class="pg-pagination" aria-label="${L('페이지 이동','Pagination','分页','ページ移動')}"><button class="pg-btn" data-page="${d.page-1}" ${d.page===1?'disabled':''}>← ${L('이전','Previous','上一页','前へ')}</button><span>${d.page} / ${Math.ceil(d.total/d.pageSize)} · ${d.total.toLocaleString()}</span><button class="pg-btn" data-page="${d.page+1}" ${d.page*d.pageSize>=d.total?'disabled':''}>${L('다음','Next','下一页','次へ')} →</button></nav>`:'';
const search=q=>`<form class="pg-search" id="live-search"><input name="q" type="search" value="${esc(q)}" aria-label="${L('검색','Search','搜索','検索')}"><button class="pg-btn">${L('검색','Search','搜索','検索')}</button></form>`;
const liveCard=(s,path)=>`<a class="pg-glass pg-lift" href="#/${path}/${encodeURIComponent(s.slug||s.id)}"><div class="pg-card-image">${livePic(s.poster_url||s.cover_url)}</div><div class="pg-card-copy"><span class="pg-eyebrow">${esc(liveDate(s.starts_at||s.published_at))}</span><h3>${esc(s.title)}</h3><p>${esc(s.subtitle||s.excerpt||s.venue_name)}</p><span>↗</span></div></a>`;
async function livePage(path,params){const api=window.KSOPCMS,s=(await api.get('settings')).data,parts=path.split('/'),page=params.get('page')||'1',q=params.get('q')||'';api.settings=s;cfg.contactEmail=s.contactEmail||'';cfg.youtube=s.youtube||cfg.youtube;
const titles={schedule:L('시리즈 일정','Series calendar','系列赛日程','シリーズ日程'),events:L('시리즈별 이벤트','Series events','系列赛事','シリーズ別イベント'),ranking:L('시즌 랭킹','Season rankings','赛季排名','シーズンランキング'),news:L('KSOP 뉴스','KSOP News','KSOP 新闻','KSOPニュース'),media:'KSOP STUDIO',about:L('KSOP 소개','About KSOP','关于KSOP','KSOPについて'),partners:L('함께하는 파트너','Our partners','合作伙伴','パートナー')};const head=k=>heading(k,esc(locale==='ko'&&s.pages?.[k]?.title?s.pages[k].title:titles[k]),esc(locale==='ko'?s.pages?.[k]?.subtitle||'':L('','Explore official KSOP updates and stories.','了解KSOP官方动态与故事。','KSOPの公式情報とストーリーをご覧ください。')));
if(path==='contact')return contactPage();if(parts[0]==='about'&&parts[1]==='apply')return parts.length===3?applyPage(parts[2]):notFound();if(path==='ranking/method')return methodPage();
if(parts[0]==='events'&&parts[1]){const e=(await api.get('events',{id:decodeURIComponent(parts[1])})).items[0];if(!e?.series_id)return notFound();return livePage('schedule/'+e.series_id+'/events/'+e.id,params)}
if(path==='schedule'){const d=await api.get('series',{page,q,phase:scheduleFilter}),first=d.items[0];return head(params.get('mode')==='events'?'events':'schedule')+(first&&page==='1'?`<article class="pg-glass pg-banner"><div class="pg-banner-image">${livePic(first.poster_url)}</div><div class="pg-banner-copy"><h2>${esc(first.title)}</h2><p>${esc(first.subtitle||first.description)}</p>${btn('schedule/'+first.slug,msg.details())}</div></article>`:'')+`<div class="pg-row">${filters('schedule',[['upcoming',L('예정','Upcoming','即将举行','開催予定')],['past',L('지난 시리즈','Past','往届','過去')]],scheduleFilter)}${search(q)}</div><div class="pg-grid">${d.items.map(x=>liveCard(x,'schedule')).join('')||liveEmpty()}</div>${pager(d)}`}
if(parts[0]==='schedule'&&parts[1]){if(parts.length!==2&&!(parts.length===4&&parts[2]==='events'))return notFound();const x=(await api.get('series',{id:decodeURIComponent(parts[1])})).items[0];if(!x)return notFound();const d=await api.get('events',{series:x.id,page});if(parts[3]&&!d.items.some(e=>e.id===parts[3]||e.slug===parts[3])){const e=(await api.get('events',{id:decodeURIComponent(parts[3]),series:x.id})).items[0];if(!e)return notFound();d.items.unshift(e)}return crumbs([[label('schedule'),'schedule'],[esc(x.title)]])+`<div class="pg-heading"><h1 tabindex="-1">${esc(x.title)}</h1><p class="pg-lead">${esc(x.subtitle)}</p></div><figure class="pg-article-cover">${livePic(x.poster_url)}</figure><dl class="pg-facts">${[[L('시작','Starts','开始','開始'),liveDate(x.starts_at)],[L('종료','Ends','结束','終了'),liveDate(x.ends_at)],[L('장소','Venue','场地','会場'),x.venue_name],[L('주소','Address','地址','住所'),x.venue_address]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||msg.pending())}</dd></div>`).join('')}</dl><div class="pg-prose">${liveText(x.description)}${liveText(x.notice)}</div><div class="pg-actions">${x.map_url?ext(api.url(x.map_url),L('지도','Map','地图','地図'),'pg-btn'):''}${x.document_url?ext(api.url(x.document_url),'PDF','pg-btn'):''}</div>`+block(L('포함된 이벤트','Series events','系列赛事','シリーズ内イベント'),d.items.map(e=>`<details class="pg-glass pg-event" ${[e.id,e.slug].includes(parts[3])?'open':''}><summary><span class="pg-event-number">${esc(e.event_number||'—')}</span><span><strong>${esc(e.title)}</strong><small>${esc(liveDate(e.starts_at))}</small></span><span class="pg-badge">${esc(e.category)}</span></summary><div class="pg-event-body">${e.banner_url||e.poster_url?`<figure class="pg-article-cover">${livePic(e.banner_url||e.poster_url)}</figure>`:''}<div class="pg-prose">${liveText(e.description)}</div><p>${esc(e.late_registration)}</p><div class="pg-actions">${e.structure_url?ext(api.url(e.structure_url),'PDF','pg-btn'):''}${e.registration_url?ext(api.url(e.registration_url),L('참가 안내','Participation','参与说明','参加案内'),'pg-btn'):''}${btn('schedule/'+x.slug+'/events/'+e.id,msg.details())}</div></div></details>`).join('')||liveEmpty())+pager(d)}
if(path==='ranking'){const d=await api.get('players',{page,q});return head('ranking')+`<div class="pg-actions">${btn('ranking/method',L('점수 계산 방식','Scoring method','积分规则','ポイント算定'))}</div>${search(q)}<div class="pg-grid">${d.items.map((p,i)=>`<a class="pg-glass pg-pad pg-lift" href="#/ranking/player/${p.slug}"><div class="pg-avatar">${p.portrait_url?livePic(p.portrait_url):esc((p.name||'K')[0])}</div><h2>${esc(p.display_name||p.name)}</h2><p>${Number(p.points).toLocaleString()} PT</p><span>${p.rank||((d.page-1)*24+i+1)}</span></a>`).join('')||liveEmpty()}</div>${pager(d)}`}
if(parts[0]==='ranking'&&parts[1]==='player'&&parts.length===3){const p=(await api.get('players',{id:decodeURIComponent(parts[2])})).items[0];if(!p)return notFound();const d=await api.get('results',{player:p.id,page}),scores=d.items.map(r=>score(Number(r.field_size),Number(r.position)));return crumbs([[label('ranking'),'ranking'],[esc(p.name)]])+`<article class="pg-glass pg-pad pg-profile"><div class="pg-avatar">${p.portrait_url?livePic(p.portrait_url):esc(p.name[0])}</div><div><h1 tabindex="-1">${esc(p.display_name||p.name)}</h1><div class="pg-prose">${liveText(p.bio)}</div></div></article><dl class="pg-facts">${[[L('시즌 점수','Season points','赛季积分','シーズンポイント'),p.points+' PT'],[L('입상 기록','Results','成绩','入賞記録'),d.total],[L('우승','Wins','冠军','優勝'),p.titles],[L('파이널','Finals','决赛','ファイナル'),p.final_tables]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`+block(L('경기 기록','Results','比赛记录','競技記録'),d.items.length?`<div class="pg-table-wrap"><table><thead><tr><th>${L('날짜','Date','日期','日程')}</th><th>${L('대회','Event','赛事','大会')}</th><th>${L('순위 / 인원','Place / field','名次 / 人数','順位 / 人数')}</th><th>${L('산정안 점수','Proposed points','方案积分','算定案ポイント')}</th></tr></thead><tbody>${d.items.map((r,i)=>`<tr><td>${esc(r.event_date)}</td><td>${esc(r.event_name)}</td><td>${r.position} / ${r.field_size}</td><td>${scores[i]}</td></tr>`).join('')}</tbody></table></div>${note(L('그래프는 검토 중인 산정안 분석값이며 확정 시즌 점수와 구분됩니다.','This chart uses the proposed formula, separate from confirmed season points.','图表采用待审计算方案，与确认的赛季积分分开。','グラフは算定案による分析値で、確定シーズンポイントとは区別されます。'))}${chart(scores,L('대회별 산정안 점수','Proposed event points','赛事方案积分','大会別算定案ポイント'))}${pager(d)}`:liveEmpty())}
if(path==='news'){const d=await api.get('news',{page,q,category:({notice:'ANNOUNCEMENT',series:'SERIES',interview:'INTERVIEW'})[newsFilter]||''});return head('news')+`<div class="pg-row">${filters('news',[['all',msg.all()],['notice',L('공지','Notices','公告','お知らせ')],['series',L('시리즈','Series','系列赛','シリーズ')],['interview',L('인터뷰','Interviews','专访','インタビュー')]],newsFilter)}${search(q)}</div><div class="pg-grid">${d.items.map(x=>liveCard(x,'news')).join('')||liveEmpty()}</div>${pager(d)}`}
if(parts[0]==='news'&&parts.length===2){const n=(await api.get('news',{id:decodeURIComponent(parts[1])})).items[0];if(!n)return notFound();return crumbs([[label('news'),'news'],[esc(n.title)]])+`<article><div class="pg-heading"><h1 tabindex="-1">${esc(n.title)}</h1><p class="pg-lead">${esc(n.excerpt)}</p><span>${esc(liveDate(n.published_at))} · ${esc(n.author)}</span></div><figure class="pg-article-cover">${livePic(n.cover_url)}</figure><div class="pg-prose">${liveText(n.body)}</div></article>`}
if(path==='media'){const d=await api.get('videos',{page,q,category:mediaFilterPage});return head('media')+`<div class="pg-actions">${ext(cfg.youtube,L('YouTube 전체보기','YouTube channel','YouTube频道','YouTubeチャンネル'),'pg-btn')}${btn('news?category=interview',L('우승자 인터뷰','Champion interviews','冠军专访','優勝者インタビュー'))}</div><div class="pg-row">${filters('media',[['all',msg.all()],['highlights',L('하이라이트','Highlights','集锦','ハイライト')],['full',L('경기 영상','Events','比赛','試合')],['shorts',L('숏츠','Shorts','短视频','ショート')],['behind',L('현장','Behind the scenes','现场','舞台裏')]],mediaFilterPage)}${search(q)}</div><div class="pg-grid pg-video-grid">${d.items.map(v=>`<a class="pg-glass pg-lift pg-video" href="${esc(api.url(v.url))}" target="_blank" rel="noopener noreferrer"><img src="${esc(api.url(v.image)||api.thumbnail(v.url))}" alt="${esc(v.title)}" loading="lazy"><span class="pg-video-caption">${esc(v.title)}</span></a>`).join('')||liveEmpty()}</div>${pager(d)}`}
if(path==='partners'){const d=await api.get('partners',{page,q});return head('partners')+search(q)+`<div class="pg-grid">${d.items.map(p=>`<article class="pg-glass pg-pad pg-partner pg-lift"><${p.url?'a':'span'} class="pg-partner-mark" ${p.url?`href="${esc(api.url(p.url))}" target="_blank" rel="noopener noreferrer"`:'tabindex="0" role="link" aria-disabled="true"'}>${partnerLogo({logo:(p.image||'').split('/').pop(),image:api.url(p.image)})}${p.url?'':`<span class="soon-badge">${msg.soon()}</span>`}</${p.url?'a':'span'}><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p></article>`).join('')||liveEmpty()}</div>${pager(d)}<div class="pg-actions">${btn('about/apply/partner',L('파트너 신청','Become a partner','申请合作','パートナーの申し込み'))}</div>`}
if(parts[0]==='about'&&parts.length<3){const d=await api.get('about',{page,...(parts[1]?{id:decodeURIComponent(parts[1])}:{})});return head('about')+`<nav class="pg-subnav">${[['company',L('회사 소개','Company','公司介绍','会社紹介')],['greeting',L('대표 인사','Greeting','代表致辞','代表挨拶')],['history',L('연혁','History','历程','沿革')]].map(([k,v])=>`<a href="#/about/${k}">${v}</a>`).join('')}</nav>`+(d.items.map(a=>`<article class="pg-block pg-glass pg-pad">${a.cover_url?`<figure class="pg-article-cover">${livePic(a.cover_url)}</figure>`:''}<h2>${esc(a.title)}</h2><p class="pg-lead">${esc(a.excerpt)}</p><div class="pg-prose">${liveText(a.body)}</div></article>`).join('')||liveEmpty())+pager(d)+block(L('함께 만드는 기회','Work with us','携手合作','協業について'),applyCards())}
return notFound();}

async function renderPage(keepScroll=false){
 const serial=++routeSerial;
 let raw=location.hash.startsWith('#/')?location.hash.slice(2):'';if(raw==='events'){raw='schedule?mode=events';history.replaceState(null,'','#/'+raw)}
 const [path,search='']=raw.split('?'),parts=path.split('/').filter(Boolean),params=new URLSearchParams(search);root.hidden=!path;$('#main').hidden=!!path;document.body.dataset.route=path||'';$('.skip').href=path?'#page-view':'#main';root.tabIndex=-1;closeMenu();
 if(!path){document.querySelectorAll('#nav a,#mobile-nav a').forEach(a=>a.removeAttribute('aria-current'));root.innerHTML='';document.title='KSOP — Korea Series of Poker';requestTick();if(!keepScroll&&location.hash==='#/')window.scrollTo({top:0,behavior:'instant'});return}
 if(parts[0]==='news'&&!parts[1]&&params.has('category'))newsFilter=['notice','series','interview'].includes(params.get('category'))?params.get('category'):'all';
 let html='',active=parts[0];
 if(parts[0]==='schedule'){if(params.get('mode')==='events')active='events';html=parts.length===1?schedulePage(active==='events'):parts.length===2?seriesPage(parts[1]):parts.length===4&&parts[2]==='events'&&['1','2','3'].includes(parts[3])?seriesPage(parts[1],parts[3]):notFound()}
 else if(path==='ranking')html=rankingPage();else if(path==='ranking/method')html=methodPage();else if(parts[0]==='ranking'&&parts[1]==='player'&&parts.length===3)html=playerPage(parts[2]);
 else if(parts[0]==='news')html=parts.length===1?newsPage():parts.length===2?articlePage(parts[1]):notFound();else if(path==='media')html=mediaPage();
 else if(parts[0]==='about')html=parts[1]==='apply'&&parts.length===3?applyPage(parts[2]):parts.length<3?aboutPage(parts[1]):notFound();else if(path==='partners')html=partnersPage();else if(path==='contact')html=contactPage();else html=notFound();
 root.setAttribute('aria-busy','true');try{html=await livePage(path,params);if(serial!==routeSerial)return}catch{if(serial!==routeSerial)return;html=empty(L('잠시 후 다시 확인해 주세요.','Please try again shortly.','请稍后重试。','少し待ってからお試しください。'))+`<button class="pg-btn" data-retry>다시 불러오기</button>`}finally{if(serial===routeSerial)root.removeAttribute('aria-busy')}
 root.innerHTML=html+footer();if(motionOn&&!keepScroll)root.animate([{opacity:.4,transform:'translateY(5px)'},{opacity:1,transform:'none'}],{duration:160,easing:'ease-out'});document.title=(root.querySelector('h1')?.textContent||'KSOP')+' · KSOP';
 document.querySelectorAll('#nav a,#mobile-nav a').forEach(a=>{const yes=a.hash==='#/'+active;a.classList.toggle('active',yes);if(yes)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 if(!keepScroll){window.scrollTo({top:0,behavior:'instant'});root.querySelector('h1')?.focus({preventScroll:true})}requestTick();
}
function go(path){if(location.hash==='#/'+path)renderPage();else location.hash='/'+path}
document.addEventListener('click',e=>{
 if(e.target.closest('.top-link')){e.preventDefault();window.scrollTo({top:0,behavior:motionOn?'smooth':'instant'});return}
 const media=e.target.closest('#media-rail .media-card');if(media?.dataset.mediaSrc&&/^https:\/\/(www\.)?(youtube\.com|youtu\.be)\//.test(media.dataset.mediaSrc)){e.preventDefault();e.stopImmediatePropagation();window.open(media.dataset.mediaSrc,'_blank','noopener,noreferrer');return}if(media){e.preventDefault();e.stopImmediatePropagation();go('media');return}
 const link=e.target.closest('a[href^="#/"]');if(link&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey&&e.button===0){e.preventDefault();e.stopImmediatePropagation();go(link.getAttribute('href').slice(2));return}
},true);
root.addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;const [fp,fq='']=location.hash.split('?');const ps=new URLSearchParams(fq);ps.delete('page');history.replaceState(null,'',fp+(ps.size?'?'+ps:''));if(b.dataset.filter==='schedule')scheduleFilter=b.dataset.value;if(b.dataset.filter==='news'){newsFilter=b.dataset.value;history.replaceState(null,'','#/news')}if(b.dataset.filter==='media')mediaFilterPage=b.dataset.value;renderPage(true).then(()=>root.querySelector(`[data-filter="${b.dataset.filter}"][data-value="${b.dataset.value}"]`)?.focus({preventScroll:true}));});
root.addEventListener('input',e=>{if(e.target.id==='player-search'){query=e.target.value;$('#player-rows').innerHTML=playerRows();$('#player-empty').hidden=!!$('#player-rows').children.length}if(e.target.closest('#inquiry-form'))$('#inquiry-review').hidden=true});
root.addEventListener('submit',e=>{
 e.preventDefault();const f=e.target;if(!f.reportValidity())return;if(f.id==='live-search'){const [p,qs='']=location.hash.slice(2).split('?'),ps=new URLSearchParams(qs);ps.set('q',new FormData(f).get('q'));ps.delete('page');go(p+'?'+ps);return}
 if(f.id==='score-form'){const n=Number(f.elements.field.value),r=Number(f.elements.place.value);if(!Number.isInteger(n)||!Number.isInteger(r)||n<2||n>100000||r<1||r>n){$('#score-output').textContent='—';$('#score-note').textContent=L('순위는 참가 선수 수 이내의 양의 정수여야 합니다.','Place must be a positive integer no greater than the field size.','名次须为不超过参赛人数的正整数。','順位は参加人数以下の正の整数で入力してください。');return}const p=score(n,r);$('#score-output').innerHTML=p.toLocaleString()+' <small>PT</small>';$('#score-note').textContent=r>Math.ceil(n*.15)?L('상위 15% 밖의 기록은 이 산정안에서 0 PT입니다.','Results outside the top 15% receive 0 PT in this proposal.','本方案中，前15%以外的成绩为0分。','本案では上位15%以外は0 PTです。'):L(`${n}명 중 ${r}위 · 규모 계수 ${Math.sqrt(Math.min(n,1000)/100).toFixed(4)} × 순위 계수 ${Math.pow((n-r)/(n-1),2).toFixed(4)} × 1,000, 반올림`,`${r} of ${n} · field ${Math.sqrt(Math.min(n,1000)/100).toFixed(4)} × finish ${Math.pow((n-r)/(n-1),2).toFixed(4)} × 1,000, rounded`,`${n}人中第${r}名，按公式四舍五入。`,`${n}名中${r}位。式に従い四捨五入。`);}
 if(f.id==='inquiry-form'){const d=new FormData(f),type=applyNames()[f.dataset.type],subject='[KSOP] '+type+' · '+String(d.get('company')).replace(/[\r\n]/g,' '),body=[type,'',L('회사·기관','Company / organization','公司 / 机构','会社・団体')+': '+d.get('company'),L('담당자','Contact','联系人','担当者')+': '+d.get('name'),'Email: '+d.get('email'),'Tel: '+d.get('phone'),'',d.get('message')].join('\n');$('#inquiry-text').textContent=body;$('#inquiry-review').hidden=false;const mail=$('#mail-inquiry');if(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cfg.contactEmail)){mail.href=`mailto:${cfg.contactEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;mail.removeAttribute('aria-disabled')}$('#inquiry-status').textContent=cfg.contactEmail?L('메일 앱에서 내용을 확인하고 발송하세요. 아직 발송되지 않았습니다.','Review and send in your email app. Nothing has been sent yet.','请在邮件应用中确认并发送。目前尚未发送。','メールアプリで確認して送信してください。まだ送信されていません。'):L('초안이 준비되었습니다. 회사 수신 메일 확인 후 발송을 연결할 수 있습니다.','Your draft is ready. Sending can be connected after the company recipient is confirmed.','草稿已准备好，确认公司收件地址后即可连接发送。','下書きができました。会社の受信先確認後に送信を接続できます。');}
});
root.addEventListener('click',async e=>{if(e.target.closest('#mail-inquiry[aria-disabled=true]'))e.preventDefault();if(e.target.id==='copy-inquiry'){try{await navigator.clipboard.writeText($('#inquiry-text').textContent);$('#inquiry-status').textContent=L('초안을 복사했습니다.','Draft copied.','已复制草稿。','下書きをコピーしました。')}catch{$('#inquiry-status').textContent=L('자동 복사를 사용할 수 없습니다. 위 내용을 선택해 복사해주세요.','Automatic copy is unavailable. Select and copy the text above.','无法自动复制，请选择上方文字手动复制。','自動コピーが使えません。上の文章を選択してコピーしてください。')}}});
root.addEventListener('pointermove',e=>{if(!motionOn||e.pointerType!=='mouse')return;const c=e.target.closest('.pg-lift');if(!c)return;const r=c.getBoundingClientRect();c.style.setProperty('--card-rx',`${(.5-(e.clientY-r.top)/r.height)*3}deg`);c.style.setProperty('--card-ry',`${((e.clientX-r.left)/r.width-.5)*4}deg`)});
root.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&e.target.src.includes('/motion/assets/media/')){e.target.src='/motion/assets/arena.webp';e.target.alt=L('영상 썸네일을 불러오지 못했습니다.','Video thumbnail unavailable.','无法加载视频缩略图。','動画サムネイルを読み込めませんでした。')}},true);
root.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){const [p,qs='']=location.hash.slice(2).split('?'),ps=new URLSearchParams(qs);ps.set('page',b.dataset.page);go(p+'?'+ps)}if(e.target.closest('[data-retry]')){window.KSOPCMS.clear();renderPage()}});
window.addEventListener('hashchange',()=>renderPage());window.addEventListener('ksop:locale',()=>{wireHome();renderPage(true)});wireHome();renderPage();
})();
